import{_ as e,c as t,o as a,ah as s,ao as p,ap as n}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"حتی یک گنجشک فراموش نمی‌شود — او هرگز نادیده گرفته نشد","description":"عیسی گفت حتی یک گنجشک بدون آگاهی پدر به زمین نمی‌افتد. متی و مزامیر درباره مراقبت خدا از حیوانات چه می‌گویند.","frontmatter":{"title":"حتی یک گنجشک فراموش نمی‌شود — او هرگز نادیده گرفته نشد","description":"عیسی گفت حتی یک گنجشک بدون آگاهی پدر به زمین نمی‌افتد. متی و مزامیر درباره مراقبت خدا از حیوانات چه می‌گویند."},"headers":[],"relativePath":"fa/pets-in-heaven/not-one-sparrow-forgotten.md","filePath":"fa/pets-in-heaven/not-one-sparrow-forgotten.md"}'),r={name:"fa/pets-in-heaven/not-one-sparrow-forgotten.md"};function i(l,o,c,h,d,f){return a(),t("div",null,[...o[0]||(o[0]=[s('<div class="pl-quote"><p>«او فقط یک حیوان کوچک بود. آیا جهان به یادش می‌ماند؟ یا فقط من؟»</p><p class="pl-quote-soft">عیسی یک بار به این پرسش پاسخ داد و پاسخ او مهربان‌تر از انتظار ماست.</p></div><section class="pl-section"><h2>۱. عیسی گفت: حتی یک گنجشک بدون پدر نمی‌افتد</h2><blockquote><p><strong>متی ۱۰:۲۹-۳۱</strong></p><p>&quot;Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.&quot;</p></blockquote><p>در روزگار عیسی، گنجشک از ارزان‌ترین چیزهایی بود که می‌شد خرید — دو تا به یک سکه کوچک. آن‌ها از آن زندگی‌هایی بودند که کسی چندان به آن‌ها توجه نمی‌کرد.</p><p>و عیسی گفت: <strong>بدون پدر شما، یکی از آن‌ها نیز بر زمین نمی‌افتد.</strong></p><p>واژه «افتادن» در اینجا به معنای مرگ است. عیسی می‌گوید مرگ ارزان‌ترین پرنده هم حادثه‌ای نیست که خدا نداند یا به آن توجه نکند. رفتن او دیده شده است. ثبت شده است.</p><p>اگر همراه شما کوچک بود، از آن دست که جهان «فقط یک حیوان» می‌نامد — این آیه برای شما نوشته شده است. خدا گنجشکان را به یاد می‌آورد. او شما را فراموش نخواهد کرد.</p></section><section class="pl-section"><h2>۲. او را خوراک داد — هیچ روزی فروگذاشت نشد</h2><blockquote><p><strong>مزامیر ۱۴۷:۹</strong></p><p>&quot;He giveth to the beast his food, and to the young ravens which cry.&quot;</p></blockquote><p>داوود در جای دیگری نیز نوشت:</p><blockquote><p><strong>مزامیر ۳۶:۶</strong></p><p>&quot;…O LORD, thou preservest man and beast.&quot;</p></blockquote><p>«انسان و حیوان» — این واژه در زبان اصلی هم حیوانات وحشی و هم اهلی را در بر می‌گیرد. خدا حیوانات را در فهرست کسانی می‌گذارد که نگه می‌دارد؛ نه به‌عنوان نکته‌ای فرعی، بلکه در کنار ما.</p><p>این یعنی چه؟ یعنی از نخستین روز تا آخرین روز، هر وعده خوراک، هر زمستان و هر ساعتی که شما خانه نبودید، آن خدا مراقب او بود. فکر می‌کردید تنها از او مراقبت می‌کنید. با خدا از او مراقبت می‌کردید.</p></section><section class="pl-section"><h2>۳. او از خدا است — و این امن‌ترین جای اوست</h2><blockquote><p><strong>مزامیر ۵۰:۱۰-۱۱</strong></p><p>&quot;For every beast of the forest is mine, and the cattle upon a thousand hills. I know all the fowls of the mountains: and the wild beasts of the field are mine.&quot;</p></blockquote><p>خدا می‌گوید: «هر حیوان جنگل از من است. چهارپایان بر هزار تپه. همه پرندگان کوه‌ها را می‌شناسم.»</p><p>حیوان شما هرگز دارایی شما نبود. او هدیه‌ای بود که خدا به مراقبت شما سپرد. و هنگامی که بخشنده هدیه آن را بازمی‌گیرد، آن را دور نمی‌اندازد — او آن را <strong>به خانه، نزد خود می‌برد</strong>.</p><p>نمی‌دانید چگونه اکنون از او مراقبت می‌کند، کجاست، یا آیا صدای شما را به یاد می‌آورد. اما می‌دانید در چه دست‌هایی است: همان دست‌هایی که گنجشکان را شمرد.</p><p class="pl-quote-soft">اگر امروز فقط می‌توانید یک جمله را نگه دارید، این را نگه دارید:</p></section><div class="pl-quote"><p>«او هرگز از دید خدا بیرون نبود. الان هم نیست.»</p></div><section class="pl-section"><h2>دعایی که می‌توانید امتحان کنید</h2><p>«خداوندا، سپاسگزارم که او را سال‌ها به من سپردی.<br>سپاسگزارم که در جایی که نمی‌دیدم از او مراقبت کردی.<br>دیگر نمی‌توانم او را در آغوش بگیرم، اما می‌دانم دستان تو از دستان من بزرگ‌تر است.<br>لطفاً از او مراقبت کن، همان‌طور که از هر گنجشک مراقبت می‌کنی.<br>و از من هم مراقبت کن، چون خیلی دلتنگم. آمین.»</p><p><a href="/fa/pets-in-heaven/">← بازگشت به Pets in Heaven</a> ｜ بعدی: <a href="/fa/pets-in-heaven/rainbow-bridge-covenant">آن سوی پل رنگین‌کمان</a></p></section><div class="pl-cta"><h2>او یک نام دارد.</h2><p>در PetLoss نام او و یک عادت کوچک که فقط شما می‌دانستید را بنویسید. آن جزئیات ارزش نگه‌داشتن دارند.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">دانلود از App Store</a></div><div class="pl-bible"><h3>بگذارید کلام خدا همراهتان بماند</h3><p>همهٔ آیات این نوشته از کتاب مقدس است. با اپلیکیشن Rainbow Bible می‌توانید هر زمان کتاب مقدس را بخوانید و ویجت «آیهٔ روز» را تنظیم کنید — نوری کوچک برای روزهایی که دلتان تنگ است.</p><div class="pl-bible-shots"><figure><img src="'+p+'" alt="ابزارک Rainbow Bible، آیهٔ ۲ تیموتائوس ۲:۱۳" loading="lazy"><figcaption>آیهٔ روز روی صفحهٔ اصلی</figcaption></figure><figure><img src="'+n+'" alt="اپ Rainbow Bible — موضوع حیوانات خانگی در بهشت، متی ۱۰:۲۹-۳۱" loading="lazy"><figcaption>در موضوع «حیوانات خانگی در بهشت» بخوانید</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">دریافت Rainbow Bible از App Store</a></div>',8)])])}const b=e(r,[["render",i]]);export{g as __pageData,b as default};
